#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_black;
float4 amzSample_black(float2 uv) { return float4(amzt_black.eval((float2(uv.x,1.0-uv.y)*float2(1920.0,1080.0)))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_black(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
layout(color) uniform half4 amzp_color;
uniform float2 amzp_position;
uniform float amzp_lowThreshold;
uniform float amzp_progressd;
uniform float amzp_thick;
uniform float amzp_alpha;
uniform float amzp_angle;
uniform float amzp_blendMode;


    float4 newLayer( float4 a, float4 b) {
    return a * (1. - b.a) + b;
    }

    float2x2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return float2x2(c, -s, s, c);
    }



   float random(float x) {

        return fract(sin(x) * 10000.);

    }

    float noise(float2 p) {

     	return random(p.x + p.y * 10000.);

    }

    float2 sw(float2 p) { return float2(floor(p.x), floor(p.y)); }
    float2 se(float2 p) { return float2(ceil(p.x), floor(p.y)); }
    float2 nw(float2 p) { return float2(floor(p.x), ceil(p.y)); }
    float2 ne(float2 p) { return float2(ceil(p.x), ceil(p.y)); }

    float smoothNoise(float2 p) {

        float2 interp = smoothstep(0., 1., fract(p));
        float s = mix(noise(sw(p)), noise(se(p)), interp.x);
        float n = mix(noise(nw(p)), noise(ne(p)), interp.x);
        return mix(s, n, interp.y);

    }

    float fractalNoise(float2 p) {

        float n = 0.;
        n += smoothNoise(p);
        n += smoothNoise(p * 2.) / 2.;
        n += smoothNoise(p * 4.) / 4.;
        n += smoothNoise(p * 8.) / 8.;
        n += smoothNoise(p * 16.) / 16.;
        n /= 1. + 1./2. + 1./4. + 1./8. + 1./16.;
        return n;

    }

    void amzRender()
    {

        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 blackTex = amzTexture(1,amzScreenNorm());

        float2 syamjaidtz = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        syamjaidtz.y*=layer.y/layer.x;

        syamjaidtz /= 1.0;
        syamjaidtz *= rot2m(amzp_angle*0.0174533);

        syamjaidtz += float2((0.0+amzp_position.x), (-350.0+amzp_position.y))*float2(-1.,1.)/500.;




    	float4 result;


    	float2 uv = syamjaidtz;
        float2 nuv = float2(uv.x - 1.0 / 6., uv.y);
        uv *= float2(1., -1.);

    	float x = fractalNoise(nuv * amzp_progressd);

        float3 final = mix(float3(x), amzTexture(1, uv).xyz, pow(abs(uv.y), 4.0));

        result = float4(final, 1.) * float4(amzp_color.rgb,1.0);

   	float4 factorr = (result + (result*amzp_thick)) * amzp_alpha;

            float4 targetLuma = factorr;
            const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float luma = dot(targetLuma.rgb, luminanceWeighting);
            float lowThresholdB = (amzp_lowThreshold*(1.0+1.0))-0.001;
            float lowThresholdA = lowThresholdB-max(1.0, 0.00001);
            float highThresholdA = (1.0*(1.0+1.0)-1.0)+0.001;
            float highThresholdB = highThresholdA+max(1.0, 0.00001);
            float lowBlend = smoothstep( lowThresholdA, lowThresholdB, luma );
            float highBlend = 1. - smoothstep( highThresholdA, highThresholdB, luma );
            float lumafx = min(lowBlend,highBlend);
            float4 factor = targetLuma*lumafx;

        float4 resultfinal;
        if( int(amzp_blendMode)==0 ) {                
            factor *= texColor.a;
            resultfinal = newLayer(texColor, factor) * texColor.a;
        } else if( int(amzp_blendMode)==1 ) {         
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( int(amzp_blendMode)==2 ) {         
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	amzOutput = mix(texColor,resultfinal,1.0) * texColor.a;
    }



half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

